import { createHmac, pbkdf2Sync, timingSafeEqual } from 'node:crypto';
import type { Cookies } from '@sveltejs/kit';
import { config } from './config.js';

/**
 * Single-owner admin auth: PBKDF2 password (generated by scripts/hash-password.mjs),
 * optional TOTP, HMAC-signed session cookie. Login attempts are throttled by the caller.
 */

/** True when admin login is usable at all. */
export function adminConfigured(): boolean {
  return config.adminPassword.length >= 8 || !!config.adminPasswordHash;
}

export function verifyCredentials(username: string, password: string): boolean {
  const userOk = safeEqual(username.trim().toLowerCase(), config.adminUsername.toLowerCase());
  // Simple mode: plain ADMIN_PASSWORD env var (single owner, secrets live in Coolify).
  if (config.adminPassword) return userOk && safeEqual(password, config.adminPassword);
  return userOk && verifyPassword(password);
}

function safeEqual(a: string, b: string): boolean {
  const ba = Buffer.from(a);
  const bb = Buffer.from(b);
  return ba.length === bb.length && timingSafeEqual(ba, bb);
}

export function verifyPassword(password: string, stored = config.adminPasswordHash): boolean {
  const [algo, iter, saltB64, hashB64] = stored.split('$');
  if (algo !== 'pbkdf2' || !iter || !saltB64 || !hashB64) return false;
  const salt = Buffer.from(saltB64, 'base64url');
  const expected = Buffer.from(hashB64, 'base64url');
  const actual = pbkdf2Sync(password, salt, Number(iter), expected.length, 'sha256');
  return actual.length === expected.length && timingSafeEqual(actual, expected);
}

function base32Decode(s: string): Buffer {
  const alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
  let bits = '';
  for (const c of s.replace(/=+$/, '').toUpperCase()) {
    const v = alphabet.indexOf(c);
    if (v < 0) continue;
    bits += v.toString(2).padStart(5, '0');
  }
  const out: number[] = [];
  for (let i = 0; i + 8 <= bits.length; i += 8) out.push(parseInt(bits.slice(i, i + 8), 2));
  return Buffer.from(out);
}

export function totpCode(secret: string, step = Math.floor(Date.now() / 30000)): string {
  const key = base32Decode(secret);
  const msg = Buffer.alloc(8);
  msg.writeBigUInt64BE(BigInt(step));
  const h = createHmac('sha1', key).update(msg).digest();
  const off = h[h.length - 1]! & 0xf;
  const code = ((h[off]! & 0x7f) << 24) | (h[off + 1]! << 16) | (h[off + 2]! << 8) | h[off + 3]!;
  return String(code % 1_000_000).padStart(6, '0');
}

export function verifyTotp(code: string, secret = config.adminTotpSecret): boolean {
  if (!secret) return true; // TOTP not configured
  const c = code.replace(/\s+/g, '');
  if (!/^\d{6}$/.test(c)) return false;
  const now = Math.floor(Date.now() / 30000);
  for (const step of [now - 1, now, now + 1]) {
    const expected = totpCode(secret, step);
    if (expected.length === c.length && timingSafeEqual(Buffer.from(expected), Buffer.from(c))) return true;
  }
  return false;
}

const COOKIE = 'ss_admin';
const TTL_SEC = 12 * 3600;

function sign(payload: string): string {
  return createHmac('sha256', config.sessionSecret).update(payload).digest('base64url');
}

export function createSession(cookies: Cookies): void {
  const exp = Math.floor(Date.now() / 1000) + TTL_SEC;
  const payload = `admin.${exp}`;
  cookies.set(COOKIE, `${payload}.${sign(payload)}`, { path: '/', httpOnly: true, sameSite: 'strict', secure: config.publicSiteUrl.startsWith('https://'), maxAge: TTL_SEC });
}

export function clearSession(cookies: Cookies): void {
  cookies.delete(COOKIE, { path: '/' });
}

export function hasValidSession(cookies: Cookies): boolean {
  if (!config.sessionSecret) return false;
  const v = cookies.get(COOKIE);
  if (!v) return false;
  const [who, exp, sig] = v.split('.');
  if (who !== 'admin' || !exp || !sig) return false;
  if (Number(exp) < Math.floor(Date.now() / 1000)) return false;
  const expected = sign(`${who}.${exp}`);
  return expected.length === sig.length && timingSafeEqual(Buffer.from(expected), Buffer.from(sig));
}
